# Функция upgrade: см. параметры, описание и вызовы ниже.
def upgrade(fish,gear,cases,locations):
    rename={'improved':'epic','epic':'professional','absolute':'secret'}
    for loc in locations:
        rows=[f for f in fish if f['location']==loc['key']]
        for i,f in enumerate(rows):
            name,lo,hi=SPECIES[loc['key']][i];f.update(name=name,min_kg=lo,max_kg=hi,rarity=rename.get(f['rarity'],f['rarity']))
        loc['required_kg']=max(f['max_kg'] for f in rows)
        loc['description']=f"{len(rows)} видов · снаряжение от {loc['required_kg']:g} кг"
    gear[:]=[g for g in gear if g['type'] in ('rod','reel','bait')]
    capacities=[150,300,700,1000,1500,2300,3000];prices=[80,400,1800,6000,18000,60000,200000]
    names={'rod':['Feeder River 150','Carbon Lake 300','Tuna Offshore 700','Big Game 1000','Ocean Power 1500','Titan Deep 2300','Abyss Master 3000'],'reel':['River 4000','Lake 6000','Offshore 8000','Big Game 10000','Ocean 14000','Titan 18000','Abyss 20000'],'bait':['Воблер River Minnow','Воблер Minnow','Блесна Silver','Джеркбейт Pike','Поппер Offshore','Силикон Deep Shad','Пилькер Abyss']}
    counts={}
    for g in gear:
        g['rarity']=rename.get(g['rarity'],g['rarity']);t=TIERS.index(g['rarity']);typ=g['type'];pair=(typ,t);v=counts.get(pair,0);counts[pair]=v+1
        luck=[0,.025,.05,.075,.10,.125,.15][t];price=prices[t]+v*prices[t]//10
        g.update(name=names[typ][t]+(f' · серия {v+1}' if v else ''),max_kg=capacities[t],luck=luck,price=price,sell_price=price//2,consumable=False,stats={'luck':luck},effect=f'До {capacities[t]} кг · удача +{luck:.1%}')
    cases.clear()
    for typ,label in [('rod','Удочки'),('reel','Катушки'),('bait','Приманки')]:
        for band,title,price,dist in [(0,'Речной',800,[65,25,8,1.7,.25,.045,.005]),(1,'Морской',4000,[15,25,35,20,4,.9,.1]),(2,'Океанский',18000,[0,5,20,45,25,4.5,.5])]:
            pool=[g for g in gear if (g.get('variant',0)%2==band%2 or band==2)]
            # each category has its own arsenal, common prices remain independent of case
            pool=[g for g in pool if g['type']==typ];counts2={r:sum(g['rarity']==r for g in pool) for r in TIERS}
            cases.append(dict(key='shore' if typ=='rod' and band==0 else f'{typ}_{band}',name=f'{title} · {label}',type=typ,icon='📦',price=price,items=[g['key'] for g in pool],weights=[dist[TIERS.index(g['rarity'])]/counts2[g['rarity']] for g in pool]))
